  `status` enum('success','failed') NOT NULL,
  `message` varchar(255) DEFAULT NULL,
  `char_name` varchar(64) DEFAULT NULL,
  `count` int(11) DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
